import numpy as np
from scipy.optimize import minimize_scalar
one=np.ones_like(t)
def build(kk):
    E=np.exp(-kk*t)
    cols=[];names=[]
    for gn,g in [('1',one),('t',t),('t2',t*t),('E',E),('tE',t*E),('E2',E*E)]:
        for pn,p in [('1',one),('P',P),('P2',P*P),('P3',P**3)]:
            cols.append(g*p);names.append(gn+'*'+pn)
    return np.column_stack(cols),names
def err(kk):
    X,_=build(kk); c,_,_,_=np.linalg.lstsq(X,dP_dt,rcond=None); r=dP_dt-X@c
    return np.mean(r**2)/np.var(dP_dt)
res=minimize_scalar(err,bounds=(0.4,0.9),method='bounded'); print(res.x,res.fun)
X,names=build(res.x); c,_,_,_=np.linalg.lstsq(X,dP_dt,rcond=None)
for n,v in zip(names,c):
